import {
  Component,
  ElementRef,
  HostListener,
  signal,
  computed,
  ChangeDetectionStrategy,
  ChangeDetectorRef,
} from '@angular/core';
import { CommonModule } from '@angular/common';
import { Router, RouterModule } from '@angular/router';
import {
  trigger,
  style,
  animate,
  transition,
  state,
} from '@angular/animations';
import { ViewChild } from '@angular/core';
import { Authservice } from '../../services/authservice';
import { UserDto } from '../../models/user';
import { UserService } from '../../services/user-service';



@Component({
  selector: 'app-dashboard',
  standalone: true,
  imports: [CommonModule, RouterModule],
  templateUrl: './dashboard.html',
  styleUrls: ['./dashboard.css'],
  animations: [
    trigger('sidebarState', [
      state('collapsed', style({ width: '60px' })),
      state('expanded', style({ width: '240px' })),
      transition('collapsed <=> expanded', animate('300ms ease')),
    ]),
    trigger('submenuToggle', [
      state('closed', style({ height: '0', opacity: 0, overflow: 'hidden' })),
      state('open', style({ height: '*', opacity: 1, overflow: 'hidden', })),
      transition('closed <=> open', animate('300ms ease')),
    ])
  ],
  changeDetection: ChangeDetectionStrategy.OnPush
})
export class Dashboard {
  @ViewChild('sidebarRef') sidebarRef!: ElementRef;
  dropdownStates = signal<{ [key: string]: boolean }>({
  inwards: false,
  master: false,
  orders: false,
  reports: false
});
  isActiveDropdown = false;
  isPinnedOpen = false;
  isSidebarOpen = signal(false);
  users: UserDto[] = [];
  isScrollable = false;
  currentUser: UserDto | null = null;
  
  sidebarState = computed(() =>
    this.isSidebarOpen() ? 'expanded' : 'collapsed'
);
wrapperScrollable = computed(() => {
  const isOpen = this.isSidebarOpen();
  const dropdowns = Object.values(this.dropdownStates()); 
  const active = isOpen && dropdowns.some(v => v);


  return active;
});


constructor(private el: ElementRef, private service: Authservice, private router: Router, private userService: UserService,  private cd: ChangeDetectorRef) {}

  ngOnInit() {
    this.userService.getUsers().subscribe(data => {
      this.users = data;
      this.cd.markForCheck();
     
    });
   this.currentUser = this.service.getCurrentUser(); 
  console.log("Current User in Dashboard:", this.currentUser);
  }


isActive: string | null = null; 
toggleDropdown(key: string) {
  this.dropdownStates.update(state => {
    const newState = { ...state, [key]: !state[key] };
    this.isActive = newState[key] ? key : null;
    return newState;
  });
}

isDropdownOpen(key: string): boolean {
  return !!this.dropdownStates()[key]; 
}

isDropdownActive(key: string): boolean {
  return this.isActive === key;
}
    onClick() {
    this.isPinnedOpen = true;
    this.isSidebarOpen.set(true);
  }
    

  onMouseEnter() {
    if (!this.isPinnedOpen) this.isSidebarOpen.set(true);
  }

  onMouseLeave() {
    if (!this.isPinnedOpen) this.isSidebarOpen.set(false);
  }

  logout() {
    this.service.logout();
    this.router.navigate(['/login']);
  }
  canAccess(permission: string): boolean {
  return this.service.hasPermission(permission);
  }
  



@HostListener('document:click', ['$event'])
onClickOutside(event: MouseEvent) {
  const clickedInsideSidebar = this.sidebarRef?.nativeElement.contains(event.target);
  if (!clickedInsideSidebar) {
    this.isPinnedOpen = false;
    this.isSidebarOpen.set(false);
    this.isActive = null;

    // Close all dropdowns
    this.dropdownStates.update(state => {
      const resetState: { [key: string]: boolean } = {};
      Object.keys(state).forEach(key => resetState[key] = false);
      return resetState;
    });
  }
}
onBtnClick(event: MouseEvent) {
  event.stopPropagation(); 
  this.isPinnedOpen = !this.isPinnedOpen;
  this.isSidebarOpen.set(this.isPinnedOpen);
}
 

}
